const fs = require("fs");
const path = require("path");

const dir = "services/com.cinejoy.tv.service";
const files = fs.readdirSync(dir).filter(f => f.endsWith(".js"));

const patterns = [
  { name: "Optional Chaining (?.)", regex: /\?\./ },
  { name: "Nullish Coalescing (??)", regex: /\?\?/ },
  { name: "Numeric Separator (\\d_\\d)", regex: /\b\d+_\d+\b/ },
  { name: "Logical Assignment (&&=, ||=, ??=)", regex: /(&&=|\|\|=|\?\?=)/ },
  { name: "Global fetch()", regex: /\bfetch\s*\(/ },
  { name: "AbortController", regex: /\bAbortController\b/ },
  { name: "AbortSignal", regex: /\bAbortSignal\b/ },
  { name: "Readable.fromWeb", regex: /Readable\.fromWeb/ },
  { name: "Array.prototype.at", regex: /\b\.at\s*\(/ },
  { name: "Object.hasOwn", regex: /\bObject\.hasOwn\b/ },
  { name: "Promise.any", regex: /\bPromise\.any\b/ },
  { name: "replaceAll", regex: /\.replaceAll\s*\(/ }
];

let totalHits = 0;
for (const f of files) {
  const content = fs.readFileSync(path.join(dir, f), "utf8");
  const lines = content.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // Ignore comments
    const trimmed = line.trim();
    if (trimmed.startsWith("//") || trimmed.startsWith("*")) continue;

    for (const p of patterns) {
      if (p.regex.test(line)) {
        console.log(`[VIOLATION CANDIDATE] ${f}:${i + 1} - ${p.name}: ${line}`);
        totalHits++;
      }
    }
  }
}
console.log(`Scan completed. Total violation candidates: ${totalHits}`);
'

