'use strict';

const fs = require('fs');
const path = require('path');

const prodFiles = [
  'http-client.js',
  'resolver.js',
  'hls-proxy.js',
  'index.js'
];

const dir = path.resolve(__dirname, '../../../services/com.cinejoy.tv.service');

function stripCommentsAndStrings(code) {
  return code
    .replace(/\/\*[\s\S]*?\*\//g, (match) => '\n'.repeat(match.split('\n').length - 1))
    .replace(/\/\/[^\n]*/g, '')
    .replace(/"(?:[^"\\]|\\.)*"/g, '""')
    .replace(/'(?:[^'\\]|\\.)*'/g, "''")
    .replace(/`(?:[^`\\]|\\.)*`/g, '``');
}

const rules = [
  { name: 'Optional chaining (?.)', regex: /\?\./ },
  { name: 'Nullish coalescing (??)', regex: /\?\?/ },
  { name: 'Numeric separator', regex: /\b\d+_\d+\b/ },
  { name: 'Logical assignment (&&=)', regex: /&&=/ },
  { name: 'Logical assignment (||=)', regex: /\|\|=/ },
  { name: 'Logical assignment (??=)', regex: /\?\?=/ },
  { name: 'Global fetch()', regex: /\b(?<![.\w])fetch\s*\(/ },
  { name: 'AbortController', regex: /\bAbortController\b/ },
  { name: 'AbortSignal', regex: /\bAbortSignal\b/ },
  { name: 'ReadableStream / fromWeb', regex: /Readable\.fromWeb|ReadableStream/ },
  { name: 'crypto.webcrypto', regex: /crypto\.webcrypto/ },
  { name: 'Promise.any', regex: /Promise\.any/ },
  { name: 'String.prototype.replaceAll', regex: /\.replaceAll\s*\(/ },
  { name: 'Array.prototype.at', regex: /\b\.at\s*\(/ },
  { name: 'Object.hasOwn', regex: /\bObject\.hasOwn\b/ }
];

let totalViolations = 0;

for (const file of prodFiles) {
  const filePath = path.join(dir, file);
  const rawCode = fs.readFileSync(filePath, 'utf8');
  const stripped = stripCommentsAndStrings(rawCode);
  const lines = stripped.split('\n');
  const rawLines = rawCode.split('\n');

  lines.forEach((line, index) => {
    for (const rule of rules) {
      if (rule.regex.test(line)) {
        console.error(`[VIOLATION] ${file}:${index + 1} (${rule.name}): ${rawLines[index].trim()}`);
        totalViolations++;
      }
    }
  });
}

if (totalViolations === 0) {
  console.log('PASS: Exactly 0 modern syntax tokens or Node 18 globals found in executable code across all production service files.');
  process.exit(0);
} else {
  console.error(`FAIL: ${totalViolations} violations found.`);
  process.exit(1);
}

'use strict';

const path = require('path');
const assert = require('assert');
const crypto = require('crypto');

const resolver = require('../../../services/com.cinejoy.tv.service/resolver');
const httpClient = require('../../../services/com.cinejoy.tv.service/http-client');

async function testCrypto() {
  console.log('[AUDIT] Initializing WebAssembly crush.wasm module...');
  const wasmModule = await resolver.initWasm();
  assert(wasmModule instanceof WebAssembly.Module, 'wasmModule must be WebAssembly.Module');

  console.log('[AUDIT] Instantiating crush.wasm and testing sealRequest...');
  const wasmInstance = await WebAssembly.instantiate(wasmModule);
  assert(typeof wasmInstance.exports.seal_request === 'function', 'seal_request export missing');
  assert(typeof wasmInstance.exports.alloc === 'function', 'alloc export missing');
  assert(typeof wasmInstance.exports.dealloc === 'function', 'dealloc export missing');

  const sealed = resolver.sealRequest(wasmInstance, {
    server: 'secret',
    type: 'movie',
    tmdbId: 550
  });

  assert(Buffer.isBuffer(sealed.responseKey), 'responseKey must be Buffer');
  assert.strictEqual(sealed.responseKey.length, 32, 'AES-256 key must be 32 bytes');
  assert.strictEqual(typeof sealed.keyId, 'number', 'keyId must be number');
  assert(Buffer.isBuffer(sealed.ephemeralPublic), 'ephemeralPublic must be Buffer');
  assert.strictEqual(sealed.ephemeralPublic.length, 64, 'ephemeralPublic body length must be 64 bytes');
  assert(Buffer.isBuffer(sealed.ciphertextBody), 'ciphertextBody must be Buffer');
  assert(sealed.ciphertextBody.length > 0, 'ciphertextBody cannot be empty');

  console.log('[AUDIT] Posting sealed ciphertext to live gateway api.wing.st/g...');
  const gatewayRes = await httpClient.request('https://api.wing.st/g', {
    method: 'POST',
    headers: {
      'Content-Type': 'text/plain;charset=UTF-8',
      'Origin': 'https://cinejoy.pk',
      'Referer': 'https://cinejoy.pk/',
      'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 Chrome/108.0.5359.211'
    },
    body: sealed.ciphertextBody,
    timeout: 10000
  });

  assert.strictEqual(gatewayRes.statusCode, 200, 'Gateway HTTP status must be 200');
  assert(gatewayRes.body.length >= 28, 'Gateway response body too short');

  console.log('[AUDIT] Testing genuine AES-256-GCM decryptResponse...');
  const decrypted = resolver.decryptResponse(
    gatewayRes.body,
    sealed.responseKey,
    sealed.keyId,
    sealed.ephemeralPublic
  );

  assert.strictEqual(typeof decrypted, 'object', 'Decrypted payload must be object');
  assert.strictEqual(decrypted.status, 200, 'Decrypted status must be 200');
  assert(decrypted.data && decrypted.data.stream, 'Decrypted stream object missing');
  const playlist = decrypted.data.stream[0].playlist;
  console.log('[AUDIT] Successfully decrypted live playlist URL:', playlist);
  assert(typeof playlist === 'string' && playlist.indexOf('http') === 0, 'Valid playlist URL required');

  console.log('[AUDIT] Testing ADVERSARIAL tampering: corrupting auth tag to verify genuine GCM verification...');
  const corruptedBody = Buffer.from(gatewayRes.body);
  corruptedBody[corruptedBody.length - 1] ^= 0xFF; // Flip last byte of GCM tag

  let tagTamperCaught = false;
  try {
    resolver.decryptResponse(
      corruptedBody,
      sealed.responseKey,
      sealed.keyId,
      sealed.ephemeralPublic
    );
  } catch (err) {
    tagTamperCaught = true;
    console.log('[AUDIT] Tamper correctly rejected by crypto.createDecipheriv:', err.message);
  }
  assert(tagTamperCaught, 'CRITICAL INTEGRITY FAILURE: Corrupted auth tag was NOT rejected by cipher!');

  console.log('[AUDIT] All cryptographic integrity checks PASSED.');
}

testCrypto().catch((err) => {
  console.error('[AUDIT ERROR]', err);
  process.exit(1);
});

