'use strict';

const assert = require('assert');
const http = require('http');
const index = require('../../../services/com.cinejoy.tv.service/index');
const httpClient = require('../../../services/com.cinejoy.tv.service/http-client');

async function testProxy() {
  console.log('[AUDIT] Starting local HTTP server on port 8099 for isolation...');
  const { server, port } = await index.startServer(8099, '127.0.0.1');
  assert.strictEqual(port, 8099, 'Port should be 8099');

  try {
    // 1. Health endpoint
    console.log('[AUDIT] Testing /health endpoint...');
    const health = await httpClient.getJson('http://127.0.0.1:8099/health');
    assert.strictEqual(health.status, 'ok');
    assert.strictEqual(health.mode, 'on-device-service');
    assert.strictEqual(health.serviceId, 'com.cinejoy.tv.service');
    assert.strictEqual(health.port, 8099);
    console.log('[AUDIT] Health response verified:', health);

    // 2. Servers endpoint
    console.log('[AUDIT] Testing /api/servers endpoint...');
    const servers = await httpClient.getJson('http://127.0.0.1:8099/api/servers');
    assert(Array.isArray(servers.servers));
    assert(servers.servers.length > 0);
    console.log('[AUDIT] Servers count:', servers.servers.length);

    // 3. Live Stream resolution endpoint
    console.log('[AUDIT] Testing /api/stream endpoint for TMDB 550...');
    const stream = await httpClient.getJson('http://127.0.0.1:8099/api/stream?tmdbId=550&type=movie&server=secret');
    assert.strictEqual(stream.success, true);
    assert(typeof stream.streamUrl === 'string');
    assert(stream.streamUrl.startsWith('http://127.0.0.1:8099/hls/proxy?url='));
    console.log('[AUDIT] Stream URL resolved:', stream.streamUrl);

    // 4. HLS Proxy Master Manifest Fetch and Rewriting
    console.log('[AUDIT] Fetching rewritten master manifest from /hls/proxy...');
    const masterText = await httpClient.getText(stream.streamUrl);
    assert(masterText.startsWith('#EXTM3U'), 'Manifest must start with #EXTM3U');
    assert(masterText.includes('http://127.0.0.1:8099/hls/proxy?url='), 'All child URLs must be rewritten to proxy');
    console.log('[AUDIT] Master manifest preview:\n' + masterText.split('\n').slice(0, 8).join('\n'));

    // Extract first variant URL
    const variantLine = masterText.split('\n').find(l => l.trim() && !l.trim().startsWith('#'));
    assert(variantLine, 'Must have at least one variant URL');

    // 5. Variant Manifest Fetch and Rewriting
    console.log('[AUDIT] Fetching rewritten variant manifest:', variantLine);
    const variantText = await httpClient.getText(variantLine);
    assert(variantText.startsWith('#EXTM3U'), 'Variant must start with #EXTM3U');
    assert(variantText.includes('http://127.0.0.1:8099/hls/proxy?url='), 'Variant segments must be rewritten');

    // Extract segment URL or init segment
    const segmentLine = variantText.split('\n').find(l => l.trim() && !l.trim().startsWith('#'));
    assert(segmentLine, 'Must have at least one media segment');
    console.log('[AUDIT] Segment proxy URL:', segmentLine);

    // 6. Media segment HTTP 206 Partial Content Range Request
    console.log('[AUDIT] Requesting byte range (bytes=0-511) from media segment...');
    const segRes = await httpClient.request(segmentLine, {
      headers: {
        'Range': 'bytes=0-511',
        'Origin': 'https://cinejoy.pk'
      }
    });
    assert(segRes.statusCode === 206 || segRes.statusCode === 200, 'Expected 206 or 200, got ' + segRes.statusCode);
    assert.strictEqual(segRes.headers['access-control-allow-origin'], '*');
    assert.strictEqual(segRes.body.length, 512, 'Must return exactly 512 bytes for range 0-511');
    console.log('[AUDIT] Received ' + segRes.body.length + ' bytes with Content-Range: ' + segRes.headers['content-range']);

    // 7. Subtitle conversion endpoint
    console.log('[AUDIT] Testing /proxy/sub subtitle conversion...');
    // Test with external subtitle or fallback URL
    if (stream.subtitles && stream.subtitles.length > 0) {
      console.log('[AUDIT] Fetching subtitle from:', stream.subtitles[0].src);
      const subRes = await httpClient.request(stream.subtitles[0].src);
      if (subRes.statusCode === 200) {
        assert(subRes.body.toString('utf8').startsWith('WEBVTT'), 'Subtitle must be converted to WEBVTT');
        console.log('[AUDIT] Subtitle successfully converted to WEBVTT!');
      }
    }

    console.log('[AUDIT] Live network and proxy pipeline PASSED.');
  } finally {
    console.log('[AUDIT] Stopping server...');
    await index.stopServer();
  }
}

testProxy().catch(err => {
  console.error('[AUDIT ERROR]', err);
  process.exit(1);
});

